    // matrix template) — the shell-hostile payload at the heart of gh-1118.
    var STAMP_SUMMARY_INLINE = 'Dispatched run: https://github.com/o/r/actions/runs/55000111\n' +
        '| Job | Result |\n| --- | --- |\n' +
