        return { sm: sm, result: result };
    }

    function stampPosts(sm) {
        return sm.capturedCliCommands.filter(function (c) {
            var cmd = c.command;
            return cmd.indexOf('-X POST') !== -1 &&
                   cmd.indexOf('/check-runs') !== -1 &&
                   cmd.indexOf('/check-runs/') === -1; // create, not PATCH
