            if (err) throw err;
            return true;
        };
        io.exec = function () {
            var err = (execResults && execResults.length > io.execs) ? execResults[io.execs] : null;
            io.execs++;
            if (err) throw err;
            return '';
        };
        io.del = function () { io.dels++; return true; };
        io.onRetry = function (e) { io.retries.push(e); };
        return io;
    }

